import React, {useState, useEffect } from 'react'
import axios from "axios";
import './MedicinePage.css'

function setCookie(cname, cvalue, exdays) {
  const d = new Date();
  d.setTime(d.getTime() + (exdays*24*60*60*1000));
  let expires = "expires="+ d.toUTCString();
  document.cookie = cname + "=" + cvalue + ";" + expires + ";path=/";
}

function getCookie(cname) {
  let name = cname + "=";
  let decodedCookie = decodeURIComponent(document.cookie);
  let ca = decodedCookie.split(';');
  for(let i = 0; i <ca.length; i++) {
    let c = ca[i];
    while (c.charAt(0) == ' ') {
      c = c.substring(1);
    }
    if (c.indexOf(name) == 0) {
      return c.substring(name.length, c.length);
    }
  }
  return "";
}

class SpeData {
  constructor(state, config) {
    this.state = state;
    this.config = config;
  }
}

const SpeState = { Default: 0, Like: 1, Could: 2, Never: 3 };
const SpeStateName = {0: "Default", 1: "Like", 2: "Could", 3: "Never" };
const medicineSpeDb = (await axios.get("/medicine/nexternat_specalites_db.json")).data; 
const medicineRanksDb = (await axios.get("/medicine/nexternat_rangs_db.json")).data;
var allSpeData = null;

const SPE_STATES_COOKIE_NAME = "SpeStates";
let speStatesCookie = "";
const SELECTED_YEARS_COOKIE_NAME = "SelectedYears";
let selectedYears = [2025, 2025];

function GetSpeStateStyleClass(speState){
  return "spe-state-" + SpeStateName[speState].toLowerCase();
}

function SpeStateCheckbox({ speData, wantedSpeState, onChange }){
  const _onChanged = e => {
      if(e.target.checked) { speData.state = wantedSpeState; }
      else { speData.state = SpeState.Default; }
      onChange(e);
  }

  return (
    <div className="spe-choice-box-checkbox-container">
      <p>{SpeStateName[wantedSpeState]}</p>
      <input type="checkbox" checked={speData.state == wantedSpeState} onChange={_onChanged}></input>
    </div>
  )
}

function SpeChoiceBox({ speData, onChanged }){
  const [seed, setSeed] = useState(0);
  const _onChanged = e => {
            setSeed(seed + 1);
            onChanged(speData)
        }

  return (
    <div className={"spe-choice-box " + GetSpeStateStyleClass(speData.state)}>
      <p className="spe-choice-box-title">{speData.config.specialite}</p>
      <SpeStateCheckbox speData={speData} wantedSpeState={SpeState.Like} onChange={_onChanged} />
      <SpeStateCheckbox speData={speData} wantedSpeState={SpeState.Could} onChange={_onChanged} />
      <SpeStateCheckbox speData={speData} wantedSpeState={SpeState.Never} onChange={_onChanged} />
    </div>
  )
}

function YearSelect({ value, onChange }) {
  return (
    <select value={value} onChange={onChange}>
      <option value={"2025"}>2025</option>
      <option value={"2024"}>2024</option>
      <option value={"2023"}>2023</option>
      <option value={"2022"}>2022</option>
      <option value={"2021"}>2021</option>
      <option value={"2020"}>2020</option>
    </select>
  )
}

function SpeLabel({ speData }) {
  return (
    <div id={speData} className={"spe-label " + GetSpeStateStyleClass(speData.state)}>
      <p>{speData.config.specialite}</p>
      { speData.config.rang_limite.min != speData.config.rang_limite.max &&
        <div className="spe-label-rank-limit-container">
          <p>Min:{speData.config.rang_limite.min}</p>
          <p>Moy:{Math.round(speData.config.rang_limite.middle)}</p>
          <p>Max:{speData.config.rang_limite.max}</p>
        </div>
      }
      { speData.config.rang_limite.min == speData.config.rang_limite.max &&
        <p>{speData.config.rang_limite.min}</p>
      }
    </div>
  )
}

function UpdateSpeRankLimits()
{
  for(const medicineSpeConfig of Object.values(medicineSpeDb)) {
    medicineSpeConfig["rang_limite"] = { "min": 1, "max": 1, "middle": 1 };
  }
  
  const startYear = Math.min(selectedYears[0], selectedYears[1]);
  const endYear = Math.max(selectedYears[0], selectedYears[1]);
  const yearDelta = Math.abs(endYear - startYear) + 1;
  for(const medicineSpeConfig of Object.values(medicineSpeDb)) {
    
    let minLimitRank = Number.MAX_SAFE_INTEGER;
    let maxLimitRank = Number.MIN_SAFE_INTEGER;
    let allLimitRankSum = 0;

    for(let i = startYear; i <= endYear; i++) {
      let yearLimitRank = 1;
      for (const medicineRankData of Object.values(medicineRanksDb)) {
        if (i != medicineRankData.annee)
          continue;
        if (medicineSpeConfig.specialite != medicineRankData.specialite)
          continue;
        const rank = medicineRankData.rang;
        if (typeof rank === 'string' || rank instanceof String)
          continue;
        
        yearLimitRank = Math.max(yearLimitRank, rank);
      }
      
      maxLimitRank = Math.max(maxLimitRank, yearLimitRank);
      minLimitRank = Math.min(minLimitRank, yearLimitRank);
      allLimitRankSum += yearLimitRank;
    }
    
    medicineSpeConfig.rang_limite.min = minLimitRank;
    medicineSpeConfig.rang_limite.max = maxLimitRank;
    medicineSpeConfig.rang_limite.middle = allLimitRankSum / yearDelta;
  }
}

export default function MedicinePage() {
  const [seed, setSeed] = useState(0);
  useEffect(() => {
    const selectedYearCookie = getCookie(SELECTED_YEARS_COOKIE_NAME);
    if(selectedYearCookie != "") {
      selectedYears[0] = parseInt(selectedYearCookie.substring(0, 4));
      selectedYears[1] = parseInt(selectedYearCookie.substring(4))
    } 

    UpdateSpeRankLimits();

    speStatesCookie = getCookie(SPE_STATES_COOKIE_NAME);
    allSpeData = {};
    for (const [key, value] of Object.entries(medicineSpeDb)) {
      
      let speState = SpeState.Default;
      if(speStatesCookie != "") {
        speState = parseInt(speStatesCookie[value.id]);
      }

      allSpeData[value.id] = new SpeData(speState, value);
    }

    if (speStatesCookie ==  "")
    {
      const speDataCount = Object.keys(allSpeData).length;
      for (let i = 0; i < speDataCount + 8; i++) {
        speStatesCookie += '0';
      }
    }

    setSeed(seed + 1)
  }, []);

  const onSpeChoiceBoxChanged = speData => {
    speStatesCookie = speStatesCookie.substring(0, speData.config.id) + speData.state.toString()[0] + speStatesCookie.substring(speData.config.id + 1);
    setCookie(SPE_STATES_COOKIE_NAME, speStatesCookie, 365);
    console.log(speStatesCookie);
    setSeed(seed + 1);
  }
  const onAnySelectedYearChanged = () => {
    const selectedYearsCookie = selectedYears[0].toString() + selectedYears[1].toString();
    setCookie(SELECTED_YEARS_COOKIE_NAME, selectedYearsCookie, 365);
    UpdateSpeRankLimits();
    setSeed(seed + 1);
  }
  const onStartYearChanged = e => {
    selectedYears[0] = parseInt(e.target.value);
    onAnySelectedYearChanged();
  }
  const onEndYearChanged = e => {
    selectedYears[1] = parseInt(e.target.value);
    onAnySelectedYearChanged();
  }

  return (
    <>
      <div className="medicine-page">
        <h1 className="medicine-title">Spécialités médecine</h1>
        { allSpeData &&
          <div className="medicine-page-content">
            <div className="spe-labels-container">
              <YearSelect value={selectedYears[0].toString()} onChange={onStartYearChanged} />
              <YearSelect value={selectedYears[1].toString()} onChange={onEndYearChanged} />
              { Object.entries(allSpeData)
                  .filter(pair => pair[1].state == SpeState.Like || pair[1].state == SpeState.Could)
                  .sort((a, b) => a[1].config.rang_limite.middle < b[1].config.rang_limite.middle)
                  .map(([key, value]) => (<SpeLabel speData={value} />
                ))
                || "loading..." }
            </div>
            <div className="spe-choice-box-container">
              { Object.entries(allSpeData).map(([key, value]) => (
                  <SpeChoiceBox speData={value} onChanged={onSpeChoiceBoxChanged}/>
                ))
              }  
            </div>
          </div>
          || "loading..."}
      </div>
    </>
  )
}
